            raise TypeError(f"Applicant at index {idx} elements must be integers")

    # Handle empty applicant list
    if not applicants:
        return (0, [])

    # Sort applicants by score descending, then registration number ascending
    sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))

    # Determine the cutoff index (using floor of 1.5 * m)
    cutoff_index = int(1.5 * m) - 1  # zero‑based index
    if cutoff_index < 0:
        # If m == 0, everyone qualifies with the maximum score as cutoff
        cutoff_score = sorted_applicants[0][1]
    elif cutoff_index >= len(sorted_applicants):
        # If 1.5*m exceeds number of applicants, all are qualified
        cutoff_score = sorted_applicants[-1][1]
    else:
        cutoff_score = sorted_applicants[cutoff_index][1]

    # Select all applicants with score >= cutoff_score
    qualified = [a for a in sorted_applicants if a[1] >= cutoff_score]

    return (cutoff_score, qualified)

