    if x0 <= 0 or y0 <= 0:
        return 0
    if x0 > y0:
        return 0
    if y0 % x0 != 0:
        return 0

    # Helper: Euclidean algorithm for GCD
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
