        bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Normalize days of week for case-insensitive check
    days_lower = {day.lower() for day in days_of_week}

    def statement_truth(speaker: str, stmt: str) -> bool | None:
        """
        Returns the truth value of a statement given the scenario,
        or None if the statement should be ignored (e.g., about days of week).
        """
        # Ignore statements about days of week
        lowered = stmt.lower()
        for day in days_lower:
            if day in lowered:
                return None

        # Check for the presence of the keyword “guilty”
        if "guilty" not in lowered:
            return None  # Other statements are ignored

        tokens = lowered.replace('.', '').replace(',', '').split()
        # Determine subject (speaker or first token)
        if tokens[0] == "i":
            subject = speaker
        else:
            subject = tokens[0].upper()

        # Find the position of “guilty” token
        try:
            guilty_index = tokens.index("guilty")
        except ValueError:
            return None

        # Detect negation (presence of “not” before “guilty”)
        negated = "not" in tokens[:guilty_index]

        # Determine if the subject is guilty in this scenario
        is_guilty_in_scenario = (subject == scenario.upper())

        # Evaluate truth value
        if negated:
            return not is_guilty_in_scenario
        else:
            return is_guilty_in_scenario

    try:
        for speaker, stmts in statements.items():
            # If speaker not present in liar_count, they are truth-tellers
            is_liar = speaker in liar_count
            for stmt in stmts:
                val = statement_truth(speaker, stmt)
                if val is None:
                    continue  # Ignored statement
                if is_liar and val:
                    return False  # Liar told a true statement
                if not is_liar and not val:
                    return False  # Truth-teller told a false statement
        return True
    except Exception:
        # In case of any unexpected error, the scenario is considered inconsistent
        return False

