def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    # basic validation
    if not isinstance(n, int) or not isinstance(m, int):
        raise ValueError("n and m must be integers")
    if n < 0 or m < 0:
        raise ValueError("n and m must be non‑negative")
    if not isinstance(a, list) or len(a) != n:
        raise ValueError("a must be a list of length n")
    for limit in a:
        if not isinstance(limit, int) or limit < 0:
            raise ValueError("All limits in a must be non‑negative integers")

    total_capacity = sum(a)
    if m > total_capacity:
        return 0

    # DP: dp[k] = number of ways to fill k pots with processed types
    dp = [0] * (m + 1)
    dp[0] = 1

    for limit in a:
        # prefix sums of dp for efficient range sum queries
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for i in range(1, m + 1):
            prefix[i] = (prefix[i - 1] + dp[i]) % MOD

        new_dp = [0] * (m + 1)
        for k in range(m + 1):
            l = k - limit
            if l <= 0:
                new_dp[k] = prefix[k]  # sum dp[0..k]
            else:
                new_dp[k] = (prefix[k] - prefix[l - 1]) % MOD
        dp = new_dp

    return dp[m] % MOD

def calculate_arrangements(n, m, a) -> int:
    """Return the number of ways to distribute m identical pots among n flower types
    with capacity limits a[0]…a[n-1], modulo 10^6+7.
    Handle invalid inputs gracefully."""
    MOD = 10**6 + 7
    try:
        n = int(n)
        m = int(m)
        if n < 0 or m < 0:
            return 0
        # Ensure a has length n
        if len(a) < n:
            a = list(a) + [0] * (n - len(a))
        else:
            a = list(a[:n])
    except Exception:
        return 0

    # Quick feasibility check
    if sum(max(0, x) for x in a) < m:
        return 0

    # DP over m, 1D optimized with sliding window
    dp = [0] * (m + 1)
    dp[0] = 1
    for cap in a:
        if cap < 0:
            cap = 0
        new = [0] * (m + 1)
        window = 0
        for j in range(m + 1):
            window += dp[j]
            if j - cap - 1 >= 0:
                window -= dp[j - cap - 1]
            new[j] = window % MOD
        dp = new

    return dp[m] % MOD

